function shotsHTML(app){const want=phone()?'narrow':'wide';const shots=app.screenshots.filter((s)=>(s.form_factor||'narrow')===want);const list=shots.length?shots:app.screenshots;if(!list.length)return'';return`<div class="ac-install__shots" data-ff="${want}" tabindex="0" role="group" aria-label="${esc(T('screenshots'))}">${list.slice(0,6).map((s)=>`<img src="${esc(s.src)}" alt="${esc(s.label||'')}" loading="lazy" decoding="async">`).join('')}</div>`;}
function benefitsHTML(list){return`<ul class="ac-install__benefits">${list.map((b)=>`<li><span class="ac-install__bicon">${ico(b.icon)}</span><span><strong>${esc(b.title)}</strong><small>${esc(b.text)}</small></span></li>`).join('')}</ul>`;}
